using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace AiBox.DevPortal.Services
{
    public class ContextSuggestionService
    {
        public List<string> GetSuggestions(string query)
        {
            var tokens = query.ToLower().Split(' ').Where(token => !string.IsNullOrEmpty(token)).ToList();
            var suggestions = new List<string>();
            foreach (var token in tokens)
            {
                suggestions.AddRange(GetSuggestionForToken(token));
            }
            var scoredSuggestions = suggestions.Select(suggestion => new { Suggestion = suggestion, Score = suggestion.ToLower().Count(c => c == token.ToLower()[0]) }).ToList();
            return scoredSuggestions.OrderByDescending(suggestion => suggestion.Score).ThenBy(suggestion => suggestion.Suggestion).Take(10).Select(suggestion => suggestion.Suggestion).ToList();
        }

        private List<string> GetSuggestionForToken(string token)
        {
            // Implement logic to retrieve suggestions based on the token
            return new List<string> { "suggestion1", "suggestion2", "suggestion3" }; // Example suggestions
        }
    }
}
